INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(21001, 'Hosea 2:11', 'Hosea', 2, 11, '&nbsp;زۀ به د هغې ټول اخترونه ختم کړم، زۀ به د هغې مياشتنۍ او د کال او د سبت د ورځې خوشحالۍ ختمې کړم او د هغې نور ټول اخترونه به ختم کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21002, 'Hosea 2:12', 'Hosea', 2, 12, '&nbsp;زۀ به د هغې د انګورو بوټى او د اينځرو ونې تباه کړم، هغې به وئيل چې دا هغه ګټه ده چې ما له خپلو عاشقانو راکړې ده. زۀ به د هغې باغونه په ځنګل بدل کړم او ځنګلى ځناور به د دې مېوه خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21003, 'Hosea 2:13', 'Hosea', 2, 13, '&nbsp;زۀ به هغې له د هغه ورځو په وجه سزا ورکړم کله چې هغې زۀ هېر کړم او بعل ته به يې خوشبويۍ سوزولې او والۍ او کالى به يې واچول او په خپلو عاشقانو پسې به روانه وه. مالِک خُدائ دا فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21004, 'Hosea 2:14', 'Hosea', 2, 14, '&nbsp;خو زۀ به يو ځل بيا هغه رضا کړم. زۀ به هغه صحرا ته بوځم، او هلته به ورسره خوږې خبرې وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21005, 'Hosea 2:15', 'Hosea', 2, 15, '&nbsp;هغې له به د انګورو باغونه بيا ورکړم او د مصيبت وادۍ نه به د اُميد دروازه جوړه کړم. هغه به زما هغه شان خبره منى لکه چې په ځوانۍ کښې يې منله، چې کله د مِصر نه راووتله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21006, 'Hosea 2:16', 'Hosea', 2, 16, '&nbsp;مالِک خُدائ فرمائى، نو په هغه ورځ به ما ته ”خپل خاوند“ ووائې او نور به ما ته ”مالِک بعل“ نۀ وائې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21007, 'Hosea 2:17', 'Hosea', 2, 17, '&nbsp;ځکه چې زۀ به د بعل معبودانو نومونه ستا د خولې نه لرې کړم، او بيا به هيڅکله د هغوئ د نومونو ذکر ستا په خولۀ نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21008, 'Hosea 2:18', 'Hosea', 2, 18, '&nbsp;په هغه وخت کښې به زۀ د ټولو ځنګلى ځناورو او د هوا مارغانو سره او په زمکه ښوئېدونکو ځناورو سره يو لوظ وکړم، نو هغوئ به زما خلقو ته نقصان نۀ رسوى. زۀ به د هغه مُلک نه د جنګ ټولې وسلې، تُورې او غشى لرې کړم او زما خلق به په امن او سکون سره ژوند تېروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21009, 'Hosea 2:19', 'Hosea', 2, 19, '&nbsp;زۀ به تا همېشه دپاره خپله ښځه جوړه کړم، او تا ته به صداقت، اِنصاف، نۀ ختمېدونکې مينه او رحم وښايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21010, 'Hosea 2:20', 'Hosea', 2, 20, '&nbsp;زۀ به په وفادارۍ سره تا خپله کړم، او بيا به تۀ ما وپېژنې چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21011, 'Hosea 2:21', 'Hosea', 2, 21, '&nbsp;مالِک خُدائ فرمائى، په هغه وخت کښې به زۀ د آسمان واورم او وريځې به پېدا کړم، او آسمان به د زمکې واورى او باران به وۀ وروم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21012, 'Hosea 2:22', 'Hosea', 2, 22, '&nbsp;زمکه به د غلې، انګورو او د زيتُونو د ونو واورى او تنده به يې مړه کړى، او دا ټول څيزونه به د يزرعيل وادۍ ته برکت ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21013, 'Hosea 2:23', 'Hosea', 2, 23, '&nbsp;په هغه وخت کښې به زۀ د بنى اِسرائيلو يو تخم وکرم او ځان دپاره به يې زرغون کړم. زۀ به هغه خلقو ته خپل رحم وښايم په چا چې رحم نۀ دے شوے، او کوم خلق چې زما قوم نۀ وُو هغوئ ته به زۀ خپل قوم ووايم، او هغوئ به راته خُدائ پاک ووائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21014, 'Hosea 3:1', 'Hosea', 3, 1, '&nbsp;مالِک خُدائ ما ته وفرمائيل، ”بيا لاړ شه او خپلې ښځې سره مينه کوه اګر چې هغه د خپل عاشق سره زنا کوى. تۀ به د هغې سره هغه شان مينه کوې لکه څنګه مينه چې زۀ د بنى اِسرائيلو سره کوم، اګر چې هغوئ نورو معبودانو ته اوړېدلى دى او بُتانو ته د کشمشو نذرانې پېش کول خوښوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21015, 'Hosea 3:2', 'Hosea', 3, 2, '&nbsp;نو ما د هغې د مهر دپاره پينځلس د سپينو زرو سيکې او يو نيم سل کلو اوربشې ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21016, 'Hosea 3:3', 'Hosea', 3, 3, '&nbsp;ما هغې ته ووئيل چې، ”تۀ به ډېره موده زما په کور کښې اوسېږې، او په دې دوران کښې به زنا نۀ کوې او هيچا سره به جنسى تعلق نۀ ساتې، ما سره هم نه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21017, 'Hosea 3:4', 'Hosea', 3, 4, '&nbsp;او د بنى اِسرائيلو به هم دغسې حال وى. تر ډېرې مودې به بادشاهان او آفسران نۀ لرى، نۀ به قربانۍ پېش کوى، نۀ به يې مقدسې ستنې وى او نۀ به يې اِمامان وى، او بُتان به هم ورسره نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21018, 'Hosea 3:5', 'Hosea', 3, 5, '&nbsp;د هغې نه پس به بنى اِسرائيليان راواپس شى او د مالِک خُدائ خپل خُدائ پاک او د خپل بادشاه داؤد د اولاد لټون به کوى. په آخرى ورځو کښې به هغوئ ريږدېدو سره مالِک خُدائ ته راځى او د هغۀ برکتونه به حاصلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21019, 'Hosea 4:1', 'Hosea', 4, 1, '&nbsp;اے بنى اِسرائيلو، د مالِک خُدائ کلام واورئ. مالِک خُدائ د دې مُلک په اوسېدونکو اِلزام لګوى چې، ”په دې مُلک کښې نۀ وفا شته او نۀ په کښې مينه شته او دا خلق خپل خُدائ پاک نۀ پېژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21020, 'Hosea 4:2', 'Hosea', 4, 2, '&nbsp;ښېرې، دروغ، قتلونه، غلاګانې او زناګانې عام شوې دى، او د قتلونو يوه سلسله روانه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21021, 'Hosea 4:3', 'Hosea', 4, 3, '&nbsp;او په دې وجه مُلک غمژن دے، او د دې اوسېدونکى به مرګى حال شى. ځنګلى ځناور، مارغان تر دې چې کبان هم مړۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21022, 'Hosea 4:4', 'Hosea', 4, 4, '&nbsp;هسې چا ته ګوته مۀ نيسئ او مۀ په بل چا د اِلزام لګولو کوشش کوئ. اے اِمامانو زما ګيله ستاسو نه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21023, 'Hosea 4:5', 'Hosea', 4, 5, '&nbsp;تاسو په رڼا ورځ تيندکونه خورئ، او ستا پېغمبران هم تاسو سره د شپې تيندکونه خورى. زۀ به ستاسو مور يعنې بنى اِسرائيل تباه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21024, 'Hosea 4:6', 'Hosea', 4, 6, '&nbsp;زما خلق تباه دى ځکه چې هغوئ سره صحيح عِلم نشته. په دې سبب چې تاسو عِلم رد کړے دے، زۀ تاسو رد کوم چې تاسو به نور زما اِمامان نۀ يئ. او لکه چې تاسو د خپل خُدائ پاک شريعت هېر کړے دے زۀ به هم ستاسو اولاد له د اِمامانو جوړېدو عزت ورنۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21025, 'Hosea 4:7', 'Hosea', 4, 7, '&nbsp;څومره چې اِمامان زياتيږى نو دومره هغوئ زما خِلاف ګناه کوى. زۀ به د هغوئ عزت په بې‌عزتۍ بدل کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21026, 'Hosea 4:8', 'Hosea', 4, 8, '&nbsp;هغوئ زما د خلقو د ګناه نذرانې خورى، هغوئ په دې لالچ کښې وى چې خلق ډېر ګناهونه وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21027, 'Hosea 4:9', 'Hosea', 4, 9, '&nbsp;اِمامانو او خلقو سره به يو شان سلوک کيږى، زۀ به اوس خلقو او اِمامانو دواړو له د هغوئ د بدو عملونو سزا ورکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21028, 'Hosea 4:10', 'Hosea', 4, 10, '&nbsp;هغوئ به خوراک کوى خو بيا به هم اوږى وى. هغوئ به لکه د هغه کنجرو په شان وى خو د دې نه به ورته هيڅ نۀ حاصليږى، ځکه چې هغوئ مالِک خُدائ پرېښے دے او نورو معبودانو ته اوړېدلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21029, 'Hosea 4:11', 'Hosea', 4, 11, '&nbsp;مے کۀ زاړۀ وى او کۀ نوى وى نو دا دواړه زما د خلقو عقل خرابوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21030, 'Hosea 4:12', 'Hosea', 4, 12, '&nbsp;هغوئ خپلو د لرګى بُتانو سره مشوره کوى، د هغوئ خيال دا وى چې د هغوئ امسا هغوئ ته د راتلونکى وخت حال وئيلے شى. د هغوئ د بُت پرستۍ شوق هغوئ لکه د زناکاره ښځې په غلطه لار روان کړى دى. هغوئ زنا کړې ده چې خپل خُدائ پاک يې پرېښے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21031, 'Hosea 4:13', 'Hosea', 4, 13, '&nbsp;د غرونو دپاسه هغوئ قربانۍ پېش کوى او هغوئ په غرونو د څېړۍ، چِنار او يا بل کوم بوټى لاندې ځکه خوشبويۍ سوزوى چې د دې سورے ډېر ښائسته وى. نو په نتيجه کښې ستاسو د لوڼو نه به کنجرې جوړې شى او ستاسو اِنږوريانې به زنا شروع کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21032, 'Hosea 4:14', 'Hosea', 4, 14, '&nbsp;زۀ به ستاسو لوڼو له سزا نۀ ورکوم کله چې هغوئ کنجرتوب شروع کوى او نۀ به ستاسو اِنږوريانو له سزا ورکوم کله چې هغوئ زنا کوى. ځکه چې بنى اِسرائيليان سړى پخپله د کنجرو سره عياشى کوى کله چې هغوئ قربانۍ پېش کوى. چا رښتيا وئيلې دى چې، ”څوک چې عقل نۀ لرى نو هغه تباه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21033, 'Hosea 4:15', 'Hosea', 4, 15, '&nbsp;اے بنى اِسرائيله، اګر چې تۀ زنا کوې، خو يهوداه دې داسې ګناه نۀ کوى. په جِلجال يا په بيت‌آون کښې عبادت مۀ کوه او نۀ چې هلته د ژوندى مالِک خُدائ په نوم قسم وخورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21034, 'Hosea 4:16', 'Hosea', 4, 16, '&nbsp;د ضدى سخى په شان بنى اِسرائيل ضدى دے. نو بيا مالِک خُدائ څنګه هغه د څران په لوئ مېدان کښې لکه د يو ګډورى په شان وڅروى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21035, 'Hosea 4:17', 'Hosea', 4, 17, '&nbsp;بنى اِسرائيل خپل ځان بُتانو ته حواله کړے دے، هغه پرېږدئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21036, 'Hosea 4:18', 'Hosea', 4, 18, '&nbsp;کله چې هغوئ ښۀ ډېر شراب وڅښى نو هغوئ د کنجرو سره په عېش عشرت کښې ډوب شى او د عزت په ځائ بې‌عزتى خوښه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21037, 'Hosea 4:19', 'Hosea', 4, 19, '&nbsp;هغوئ به داسې ورک شى لکه چې هوا يې يوسى او هغوئ به د خپلو قربانو په وجه په شرم وشرميږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21038, 'Hosea 5:1', 'Hosea', 5, 1, '&nbsp;”اے اِمامانو، دې ته غوږ ونيسئ. اے بنى اِسرائيلو واورئ، اے د شاهى خاندان خلقو توجو وکړئ. عدالت ستاسو خلاف فېصله کړې ده. ځکه چې تاسو د خلقو دپاره دام جوړ شوئ چې په مصفاه او تبور کښې مو د بُتانو عبادت کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21039, 'Hosea 5:2', 'Hosea', 5, 2, '&nbsp;او په شِطيم کښې تاسو ژوره کنده کنستې ده، خو زۀ به تاسو ټولو له سزا درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21040, 'Hosea 5:3', 'Hosea', 5, 3, '&nbsp;زۀ بنى اِسرائيل ډېر ښۀ پېژنم، د دې بدى زما نه پټه نۀ ده. بنى اِسرائيلو کنجرتوب کړے دے چې زۀ يې پرېښے يم او هغه ناپاکه دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21041, 'Hosea 5:4', 'Hosea', 5, 4, '&nbsp;د خلقو بد عملونه هغوئ ته دا اجازت نۀ ورکوى چې خپل خُدائ پاک ته واپس راوګرځى. ځکه چې د زنا عادت هغوئ په خپل قابو کښې اخستى دى او هغوئ مالِک خُدائ نۀ پېژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21042, 'Hosea 5:5', 'Hosea', 5, 5, '&nbsp;د بنى اِسرائيلو غرور د هغوئ خِلاف ګواهى ورکوى. هغوئ به د خپلې ګناه په وجه راوغورزيږى او د يهوداه خلق به هم ورسره راوغورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21043, 'Hosea 5:6', 'Hosea', 5, 6, '&nbsp;کله چې هغوئ خپلو رَمو او څاروو سره د مالِک خُدائ لټون له راځى، نو هغوئ به يې پېدا نۀ کړے شى ځکه چې هغۀ دوئ پرېښى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21044, 'Hosea 5:7', 'Hosea', 5, 7, '&nbsp;هغوئ د مالِک خُدائ سره بې‌وفائى کړې ده، او حراميان بچى يې پېدا کړى دى. نو اوس به نوې مياشت هغوئ سره د جائيداد لواړ تېر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21045, 'Hosea 5:8', 'Hosea', 5, 8, '&nbsp;په جبعه کښې د جنګ دپاره بيګلې وغږوئ. په راما کښې د خبردارى دپاره آواز وکړئ. په بيت‌آون کښې جنګى نعره ووهئ. اے بنيامينيانو، تاسو مخکښې شئ مونږ درپسې يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21046, 'Hosea 5:9', 'Hosea', 5, 9, '&nbsp;د عدالت ورځ راروانه ده او د اِسرائيل مُلک به تباه شى. اے بنى اِسرائيلو، زۀ دا اعلان کوم چې داسې به ضرور کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21047, 'Hosea 5:10', 'Hosea', 5, 10, '&nbsp;مالِک خُدائ فرمائى، ”د يهوداه آفسران داسې دى څوک چې د زمکې حدود زياتولو دپاره پولې بې‌ځايه کوى. نو زۀ به خپله غصه په هغوئ باندې لکه د سېلاب په شان نازله کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21048, 'Hosea 5:11', 'Hosea', 5, 11, '&nbsp;په اِسرائيل به ظلم وشى او زما د فېصلې لاندې به چخڼى شى، ځکه چې هغۀ به په شوق د بې‌کاره بُتانو عبادت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21049, 'Hosea 5:12', 'Hosea', 5, 12, '&nbsp;زۀ به اِسرائيل داسې تباه کړم لکه چې چينجے وړۍ خورى. او يهوداه به لکه د سخا ډډ لرګى په شان کمزورے کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21050, 'Hosea 5:13', 'Hosea', 5, 13, '&nbsp;کله چې اِسرائيل خپله بيمارى او يهوداه خپل زخمونه وليدل، نو اِسرائيل لاړل چې د اسور د لوئ بادشاه نه مدد وغواړى، خو هغۀ نۀ دوئ ته شفا ورکولے شوه او نۀ يې د دوئ د زخمونو علاج کولے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21051, 'Hosea 5:14', 'Hosea', 5, 14, '&nbsp;زۀ به په اِسرائيل باندې لکه د ازمرى په شان او په يهوداه باندې لکه د تکړه ازمرى په شان حمله وکړم. زۀ به په خپله هغوئ ټوکړې ټوکړې کړم، زۀ به هغوئ راکاږم او هيڅ څوک به يې رانه خلاصولے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21052, 'Hosea 5:15', 'Hosea', 5, 15, '&nbsp;زۀ به بيا خپل ځائ ته راواپس شم، ترڅو چې هغوئ خپله ملامتيا ومنى او ما ته راوګرځى. او چې کله په هغوئ مصيبت راشى نو هغوئ به زما سخت تلاش شروع کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21053, 'Hosea 6:1', 'Hosea', 6, 1, '&nbsp;”راځئ، چې مالِک خُدائ ته راوګرځُو. هغۀ مونږ تيکه تيکه کړى يُو، خو اوس به هغه مونږ له شفا راکوى. هغۀ مونږ زخمى کړى يُو، خو اوس به هغه زمونږ د زخمونو مرهم پټۍ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21054, 'Hosea 6:2', 'Hosea', 6, 2, '&nbsp;په ډېر لږ وخت کښې به هغه مونږ بحال کړى او په لږ وخت کښې به شفا راکړى او داسې به مونږ د هغۀ په حضور کښې ژوند تېروو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21055, 'Hosea 6:3', 'Hosea', 6, 3, '&nbsp;راځئ چې هغه وپېژنو، راځئ چې پوره کوشش وکړو چې مالِک خُدائ ښۀ وپېژنو. هغه به يقيناً مونږ له داسې راځى لکه څنګه چې هر سحر نمر راخېژى، لکه څنګه چې د ژمې باران وريږى، لکه څنګه چې د سپرلى باران زمکه اوبۀ کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21056, 'Hosea 6:4', 'Hosea', 6, 4, '&nbsp;مالِک خُدائ فرمائى، ”اے اِسرائيله او يهوداه، زۀ تاسو سره څۀ وکړم؟ ستاسو مينه ما سره لکه د سحر د دوند په شان زر ختمه شى او لکه د سحر د پرخې په شان زر والوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21057, 'Hosea 6:5', 'Hosea', 6, 5, '&nbsp;نو دا ځکه ما د خپلو پېغمبرانو په لاس تاسو ټوټې ټوټې کړئ، او د خپلې خولې په کلام مې تاسو ووژلئ. زما د اِنصاف رڼا لکه د نمر راخېژى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21058, 'Hosea 6:6', 'Hosea', 6, 6, '&nbsp;زۀ غواړم چې تاسو وفادارى وښايئ نه چې قربانى وکړئ. ستاسو د سوزېدونکو نذرانو نه زيات زۀ غواړم چې تاسو ما وپېژنئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21059, 'Hosea 6:7', 'Hosea', 6, 7, '&nbsp;خو په آدم نومې ښار کښې تاسو لوظ مات کړو او هلته مو ما سره بې‌وفائى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21060, 'Hosea 6:8', 'Hosea', 6, 8, '&nbsp;جِلعاد ښار د بدعملو نه ډک دے، هر طرف ته د وينې داغونه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21061, 'Hosea 6:9', 'Hosea', 6, 9, '&nbsp;اِمامان د ډاکوانو د هغه قبيلې په شان دى چې هغوئ د چا د لوټ کولو دپاره غلى ناست وى. هغوئ د شِکم په لاره باندې قتلونه کوى، او هر قسم ګناه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21062, 'Hosea 6:10', 'Hosea', 6, 10, '&nbsp;ما په اِسرائيلو کښې ډېر بد بد کارونه ليدلى دى. زما خلقو د بُتانو د عبادت په وجه خپل ځانونه ناپاکه کړى دى چې زناکارى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21063, 'Hosea 6:11', 'Hosea', 6, 11, '&nbsp;اے د يهوداه خلقو، ما ستاسو د سزا وخت هم مقرر کړے دے، اګر چې ما غوښتل چې هغوئ بحال کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21064, 'Hosea 7:1', 'Hosea', 7, 1, '&nbsp;”کله چې زۀ اِسرائيلو له شفا ورکول غواړم نو د دوئ ګناه راته څرګنده شى او د سامريه بدکارى راته ښکاره شى. ځکه چې هغوئ د چل کارونه کوى، غلۀ کورونو ته وراوړى او غلاګانې کوى، او ډاکوان په لارو کښې خلق لوټ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21065, 'Hosea 7:2', 'Hosea', 7, 2, '&nbsp;هغوئ د دې نه ناخبره دى چې ما ته د هغوئ ټول بد عملونه ياد دى. د هغوئ ګناهونه په هر ځائ کښې څرګند دى، دا ټول ما ته ښکارى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21066, 'Hosea 7:3', 'Hosea', 7, 3, '&nbsp;هغوئ په خپلو بدو منصوبو بادشاه خوشحالوى، او په دروغو وئيلو باندې آفسران خوشحالوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21067, 'Hosea 7:4', 'Hosea', 7, 4, '&nbsp;هغوئ ټول زناکاران دى. هغوئ لکه د سور کړے شوى تنور په شان دى چې دومره ګرم وى چې د نانبائى د لاس وروړو ضرورت ورته نۀ وى. کۀ هغه اوړۀ واغږى او هغه خمبيره شى نو بيا هم تنور دومره ګرم وى چې روټۍ به پرې پخې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21068, 'Hosea 7:5', 'Hosea', 7, 5, '&nbsp;په شاهى جشن کښې آفسران په ميو ځان نشه کړى، او مسخره کوونکو له لاس ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21069, 'Hosea 7:6', 'Hosea', 7, 6, '&nbsp;د هغوئ زړونه لکه د تنور په شان د خپلو بدو منصوبو په وجه سوزى. د هغوئ غصه ټوله شپه بې‌لمبو سوزى او په سحر کښې لکه د اور لمبې وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21070, 'Hosea 7:7', 'Hosea', 7, 7, '&nbsp;هغوئ ټول لکه د تنور لمبه دى او خپل حکمرانان لواړ تېروى. د هغوئ ټول بادشاهان راپرېوتل، خو يو هم ما ته دُعا نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21071, 'Hosea 7:8', 'Hosea', 7, 8, '&nbsp;بنى اِسرائيل خپل ځان لکه د اوړو په شان نورو قومونو سره اغږلے دے. بنى اِسرائيل لکه د هغه روټۍ په شان دے چې صرف يو مخ يې پوخ شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21072, 'Hosea 7:9', 'Hosea', 7, 9, '&nbsp;د پردى مُلک خلق د هغۀ طاقت خورى خو هغۀ ته د دې پته نشته، د هغۀ سر د سپينو وېښتو نه ډک دے خو هغۀ ته د دې پته نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21073, 'Hosea 7:10', 'Hosea', 7, 10, '&nbsp;د بنى اِسرائيل غرور د هغۀ خِلاف ګواهى ورکوى، خو بيا هم هغوئ مالِک خُدائ خپل خُدائ پاک ته نۀ راګرځى. د دې هر څۀ باوجود هغوئ د هغۀ د لټون نه اِنکار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21074, 'Hosea 7:11', 'Hosea', 7, 11, '&nbsp;بنى اِسرائيل د کم عقلې ګوګوشتکې په شان دى چې په آسانه دوکه کيږى. اول يې مِصر د مدد دپاره راوغوښتو او بيا يې د پناه دپاره اسور ته ورمنډه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21075, 'Hosea 7:12', 'Hosea', 7, 12, '&nbsp;خو چې کله هغوئ الوځى رالوځى نو زۀ به پرې خپل جال ورلړه کړم او د هوا د مارغانو په شان به يې ښکته راکوز کړم. د هغوئ د بدعملۍ په وجه به زۀ سزا ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21076, 'Hosea 7:13', 'Hosea', 7, 13, '&nbsp;په هغوئ افسوس، ځکه چې هغوئ زما نه تښتېدلى دى. هغوئ تباه دى، ځکه چې هغوئ زما خِلاف سرکشى کړې ده. ما غوښتل چې هغوئ بچ کړم، خو هغوئ زما خلاف دروغ وئيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21077, 'Hosea 7:14', 'Hosea', 7, 14, '&nbsp;هغوئ د زړۀ د اخلاصه ما ته سوال نۀ دے کړے، خو هغوئ د پرېشانۍ نه په خپلو کټونو کښې ژړاګانې کوى. هغوئ د غلې يا د ميو حاصلولو دپاره معبودانو ته خپل ځانونه غوڅوى، خو هغوئ زما خلاف بغاوت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21078, 'Hosea 7:15', 'Hosea', 7, 15, '&nbsp;اګر چې هم ما د هغوئ تربيت وکړو او مضبوط مې کړل، خو هغوئ زما خِلاف بدې منصوبې جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21079, 'Hosea 7:16', 'Hosea', 7, 16, '&nbsp;هغوئ د خُدائ تعالىٰ نه بغېر هر خوا ګورى. هغوئ د کږې ليندې په شان نا اعتباره دى. د هغوئ آفسران به د خپلې سپکې خولې د لاسه په تُوره مړۀ شى او مِصريان به په هغوئ پورې خندا کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21080, 'Hosea 8:1', 'Hosea', 8, 1, '&nbsp;”د خبردارى دپاره بيګل وغږوئ. دشمنان د ټپوس په شان د مالِک خُدائ په کور راغوټه کيږى، ځکه چې هغوئ ما سره لوظ مات کړے دے او زما د شريعت خِلاف‌ورزى يې کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21081, 'Hosea 8:2', 'Hosea', 8, 2, '&nbsp;اوس بنى اِسرائيل ما ته مِنت زارى کوى چې، زمونږ مدد وکړه ځکه چې تۀ زمونږ خُدائ پاک يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21082, 'Hosea 8:3', 'Hosea', 8, 3, '&nbsp;خو بنى اِسرائيلو هغه څۀ رد کړى دى څۀ چې ښۀ دى، نو دشمن به هغۀ پسې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21083, 'Hosea 8:4', 'Hosea', 8, 4, '&nbsp;هغوئ زما د اجازت نه بغېر بادشاهان جوړ کړل، هغوئ زما د رضا نه بغېر مشران مقرر کړل. هغوئ د خپلو سرو زرو او سپينو زرو نه بُتان جوړ کړى دى او په ځان يې پخپله تباهى راوستې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21084, 'Hosea 8:5', 'Hosea', 8, 5, '&nbsp;اے سامريې. ما ستا دا سخے بُت رد کړے دے. زما غصه ستا خلاف ده، تاسو د صفا کېدو قابل نۀ يئ ترڅو پورې به ستاسو دا حالت جارى وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21085, 'Hosea 8:6', 'Hosea', 8, 6, '&nbsp;اے بنى اِسرائيله، تۀ چې د کوم بُت عبادت کوې دا يو کسبګر جوړ کړے دے، دا خُدائ پاک نۀ دے. په سامريه کښې سخے بُت به ټوټې ټوټې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21086, 'Hosea 8:7', 'Hosea', 8, 7, '&nbsp;هغوئ د هوا تخم کَرى، او د طوفان فصل به رېبى. د غلې فصل ولاړ دے خو وَږى په کښې نۀ ښکارى نو د خوراک مِلاوېدو په کښې څۀ امکان نشته. خو کۀ څۀ غله په کښې وى هم، نو د پردى مُلک خلق به يې وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21087, 'Hosea 8:8', 'Hosea', 8, 8, '&nbsp;بنى اِسرائيل لواړ تېر کړے شوى دى. اوس هغوئ په نورو قومونو کښې خوارۀ شوى دى او د بېکاره لوښى په شان پراتۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21088, 'Hosea 8:9', 'Hosea', 8, 9, '&nbsp;هغوئ اسوريانو له د مدد دپاره تلى دى، لکه څنګه چې يوې ځنګلى خرې وار راوړے وى. دغسې بنى اِسرائيل لکه د کنجرې خپل ځان په عاشقانو خرڅ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21089, 'Hosea 8:10', 'Hosea', 8, 10, '&nbsp;اګر چې دوئ خپل ځان په ډېرو قومونو خرڅ کړے دے، خو اوس به زۀ هغوئ يو ځائ ته راغونډ کړم او سزا به ورکړم. د هغوئ بادشاه او شهزادګان به زر د جزيې لاندې په لړزان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21090, 'Hosea 8:11', 'Hosea', 8, 11, '&nbsp;اګر چې بنى اِسرائيل د ګناه د لرې کولو دپاره ډيرې قربان‌ګاه جوړې کړې دى، خو هم دغه قربان‌ګاه د هغوئ دپاره د ګناه ځايونه شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21091, 'Hosea 8:12', 'Hosea', 8, 12, '&nbsp;اګر چې ما هغوئ دپاره خپل شريعت ډېر تشريح کړو، خو هغوئ ځان داسې ناغرضه کړو لکه چې دا شريعت هډو د هغوئ دپاره نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21092, 'Hosea 8:13', 'Hosea', 8, 13, '&nbsp;هغوئ ما ته قربانۍ پېش کوى او د قربانۍ غوښې خورى. خو زۀ، مالِک خُدائ د هغوئ نه رضا نۀ يم، ما ته به د هغوئ ګناهونه ياد وى او سزا به ورته ورکړم، او هغوئ به مِصر ته واپس ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21093, 'Hosea 8:14', 'Hosea', 8, 14, '&nbsp;بنى اِسرائيلو خپل خالِق هېر کړے دے او شاهى محلونه يې جوړ کړى دى، او يهوداه د پَخو دېوالونو ډېر ښارونه جوړ کړى دى. خو زۀ به د هغوئ په ښارونو اور نازل کړم او هغه به د هغوئ محلونه وسوزوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21094, 'Hosea 9:1', 'Hosea', 9, 1, '&nbsp;اے بنى اِسرائيلو، د نورو قومونو په شان خوشحالى مۀ کوئ. تاسو د خپل خُدائ پاک نه اوړېدلى يئ او د هغۀ سره مو بې‌وفائى کړې ده. تاسو خپل ځانونه لکه د کنجرو په شان خرڅوئ او په هر درمند کښې د نورو معبودانو عبادت کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21095, 'Hosea 9:2', 'Hosea', 9, 2, '&nbsp;خو اوس به ستاسو د خوراک دپاره غله کافى نۀ وى او نۀ به درسره دومره انګور وى چې مے ترېنه وباسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21096, 'Hosea 9:3', 'Hosea', 9, 3, '&nbsp;بنى اِسرائيليان به د مالِک خُدائ په مُلک کښې نۀ پاتې کيږى، بلکې هغوئ به مِصر ته واپس ځى او د اسور په مُلک کښې به حرام څيزونه خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21097, 'Hosea 9:4', 'Hosea', 9, 4, '&nbsp;هغوئ به مالِک خُدائ ته نۀ د ميو نذرانې وړاندې کړے شى او نۀ به يې په قربانيانو رضا کړے شى. د هغوئ د نذرانو روټۍ به د ماتم کوونکو د روټۍ په شان وى يعنې څوک هم چې دغه روټۍ خورى نو هغه به ناپاک شى. په دې به هغوئ صرف خپله لوږه ختموى، خو د مالِک خُدائ کور ته به د نذرانې په توګه نۀ شى وړلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21098, 'Hosea 9:5', 'Hosea', 9, 5, '&nbsp;تاسو به د اختر په ورځ څۀ کوئ، د مالِک خُدائ اختر به څنګه کوئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21099, 'Hosea 9:6', 'Hosea', 9, 6, '&nbsp;ګورئ کۀ هغوئ د تباهۍ نه وتښتى هم، نو مِصر به هغوئ رايوځائ کړى، او ميمفِس به يې ښخ کړى. د هغوئ د سپينو زرو خزانې به په لوخو کښې ورکې شى، او د هغوئ په کورونو کښې به د ازغو بوټى راوټوکيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21100, 'Hosea 9:7', 'Hosea', 9, 7, '&nbsp;نو د سزا وخت راغلے دے، د حساب کِتاب وخت رارسېدلے دے. بنى اِسرائيل دې ځان پوهه کړى. تاسو وايئ چې، ”دا پېغمبر کم عقل دے. دا د روح والا بنده پاګل دے.“ نو ځکه څومره چې ستاسو ګناه غټه ده نو دومره ستاسو نفرت هم زيات دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');